static int ov5647_get_supported_value(FAR struct imgsensor_s *sensor,
                                      uint32_t id,
                                      FAR imgsensor_supported_value_t *value)
{
  FAR struct ov5647_s *priv = (FAR struct ov5647_s *)sensor;
  FAR imgsensor_capability_range_t *range;
  FAR const struct ov5647_mode_s *mode;

  if (value == NULL)
    {
      return -EINVAL;
    }

  range = &value->u.range;

  switch (id)
    {
      case IMGSENSOR_ID_EXPOSURE_ABSOLUTE:

        /* Exposure is a number of lines, and those lines have to fit inside
         * the frame the mode produces, so the ceiling follows the mode: a
         * count legal in one is not necessarily legal in another.
         *
         * Answer for the mode the last request named, which is the one the
         * next stream will run at.  `mode` below is what the sensor is
         * programmed for now, and is the answer before anything has been
         * asked for -- or after a stream has started with no request since.
         */

        mode = priv->requested != NULL ? priv->requested : priv->mode;

        value->type = IMGSENSOR_CTRL_TYPE_INTEGER;
        range->minimum = (int64_t)OV5647_EXPOSURE_MIN;
        range->maximum = (int64_t)OV5647_MODE_EXPOSURE_MAX(mode);
        range->step = 1;

        /* What a stream started with no request runs at: the ceiling, which
         * is what ov5647_initialize() resolves the driver's default to.
         */

        range->default_value = (int64_t)OV5647_MODE_EXPOSURE_MAX(mode);
        break;

      case IMGSENSOR_ID_ISO_SENSITIVITY:

        /* Unlike the exposure ceiling, the gain range is the part's and not
         * a mode's.  The default is where the driver starts rather than the
         * smallest value it accepts, and the two are not the same.
