        value->type = IMGSENSOR_CTRL_TYPE_INTEGER;
        range->minimum = (int64_t)OV5647_ANALOG_GAIN_MIN;
        range->maximum = (int64_t)OV5647_ANALOG_GAIN_MAX;
        range->step = 1;
        range->default_value = (int64_t)OV5647_ANALOG_GAIN_DEFAULT;
        break;

      default:
        return -ENOTSUP;
    }

